    expect(TICKS_PER_MINUTE).toBe(600_000_000);
    expect(TICKS_PER_HOUR).toBe(36_000_000_000);
    expect(TICKS_PER_MINUTE).toBe(TICKS_PER_SECOND * 60);
    expect(TICKS_PER_HOUR).toBe(TICKS_PER_MINUTE * 60);
  });
