    expect(a).toEqual(b);
  });
});

import { describe, it, expect } from 'vitest';
import { pickDefaultAudio } from '../src/Audio';
import type { StreamAudioTrack } from '../src/AudioTrack';

function track(id: string, language: string): StreamAudioTrack {
  // ...
}

describe('pickDefaultAudio', () => {

  it('returns index of matching track when language matches preferred', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'en-US'),
      track('t2', 'es-ES'),
      track('t3', 'fr-FR'),
    ];

    const result = pickDefaultAudio(tracks, ['en-US']);

    expect(result).toBe(0);
  });

  it('returns index of second track when first preferred language matches second track', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'fr-FR'),
      track('t2', 'de-DE'),
      track('t3', 'en-US'),
    ];

    const result = pickDefaultAudio(tracks, ['de-DE']);

    expect(result).toBe(1);
  });

  it('returns index of first match when multiple preferred languages are tried in order', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'ja-JP'),
      track('t2', 'ko-KR'),
      track('t3', 'zh-CN'),
    ];

    const result = pickDefaultAudio(tracks, ['en-US', 'ja-JP']);

    expect(result).toBe(0);
  });

  it('handles BCP47 primary language tag extraction (en-US matches en)', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'en'),
      track('t2', 'es'),
    ];

    const result = pickDefaultAudio(tracks, ['en-US']);

    expect(result).toBe(0);
  });

  it('handles case-insensitive language matching', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'EN-US'),
      track('t2', 'ES-ES'),
    ];

    const result = pickDefaultAudio(tracks, ['en-us']);

    expect(result).toBe(0);
  });


  it('returns 0 when tracks array is empty', () => {
    const tracks: StreamAudioTrack[] = [];

    const result = pickDefaultAudio(tracks, ['en-US']);

    expect(result).toBe(0);
  });

  it('returns 0 when preferredLanguages array is empty', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'en-US'),
    ];

    const result = pickDefaultAudio(tracks, []);

    expect(result).toBe(0);
  });

  it('returns 0 when no track language matches any preferred language', () => {
    const tracks: StreamAudioTrack[] = [
      track('t1', 'fr-FR'),
      track('t2', 'de-DE'),
    ];

    const result = pickDefaultAudio(tracks, ['en-US', 'ja-JP']);

    expect(result).toBe(0);
  });

  it('returns 0 (fallback to first track) when track language is null/undefined', () => {
    const tracksWithUndefined: StreamAudioTrack[] = [
      { id: 't1', codec: 'aac', language: undefined as unknown as string, channels: 2 },
      track('t2', 'en-US'),
    ];

    const result = pickDefaultAudio(tracksWithUndefined, ['en-US']);

    expect(result).toBe(1);
  });

  it('handles tracks with null language gracefully (skips to next)', () => {
    const tracks: StreamAudioTrack[] = [
      { id: 't1', codec: 'aac', language: null as unknown as string, channels: 2 },
      track('t2', 'en-US'),
    ];

    const result = pickDefaultAudio(tracks, ['en-US']);

    expect(result).toBe(1);
  });
});

import { describe, it, expect } from 'vitest';
import { pickDisplayRating, type MediaItemRatingSource } from '../src/Rating';

describe('pickDisplayRating', () => {

  it('returns rating_score when present and not null', () => {
    const item: MediaItemRatingSource = {
      rating_score: 7.5,
      metadata_json: null,
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(7.5);
  });

  it('returns numeric metadata_json.rating when rating_score is absent (undefined)', () => {
    const item: MediaItemRatingSource = {
      metadata_json: { rating: 6.5 },
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(6.5);
  });

  it('returns rating_score even when metadata_json is also present', () => {
    const item: MediaItemRatingSource = {
      rating_score: 8.0,
      metadata_json: { rating: 6.5 },
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(8.0); // rating_score wins
  });

  it('returns numeric metadata_json.rating when rating_score is null', () => {
    const item: MediaItemRatingSource = {
      rating_score: null,
      metadata_json: { rating: 5.5 },
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(5.5);
  });

  it('handles integer rating_score correctly', () => {
    const item: MediaItemRatingSource = {
      rating_score: 8,
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(8);
  });

  it('handles integer metadata_json.rating correctly', () => {
    const item: MediaItemRatingSource = {
      metadata_json: { rating: 7 },
    };

    const result = pickDisplayRating(item);

    expect(result).toBe(7);
  });


  it('returns null when rating_score is null and metadata_json.rating is a string (MPAA content rating)', () => {
    const item: MediaItemRatingSource = {
      rating_score: null,
      metadata_json: { rating: 'PG-13' },
    };

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });

  it('returns null when both rating_score and metadata_json are null', () => {
    const item: MediaItemRatingSource = {
      rating_score: null,
      metadata_json: null,
    };

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });

  it('returns null when rating_score is undefined and metadata_json is undefined', () => {
    const item: MediaItemRatingSource = {
    };

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });

  it('returns null when metadata_json.rating is a string content rating even if rating_score is absent', () => {
    const item: MediaItemRatingSource = {
      metadata_json: { rating: 'R' },
    };

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });

  it('returns null when metadata_json.rating is null', () => {
    const item: MediaItemRatingSource = {
      metadata_json: { rating: null },
    };

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });

  it('skips non-numeric values in metadata_json.rating (e.g. boolean)', () => {
    const item = {
      metadata_json: { rating: true },
    } as unknown as MediaItemRatingSource;

    const result = pickDisplayRating(item);

    expect(result).toBeNull();
  });
});
